'use strict';
let paymentIntent='',currentUser=null,ownerLoginAllowed=false,authReady=false,scanner=null,passTimer=null,lastScannedToken='',authTab='login',settingsTab='payments';
let canSetup=false;
const baseRender=render,baseHeader=header,baseRegistrationModal=registrationModal,baseSubmitRegistration=submitRegistration,basePay=pay,baseEditProfile=editProfile,baseCloseModal=closeModal,basePayments=payments,baseMemberOverview=memberOverview,baseMemberMembership=memberMembership;
async function api(path,body){const response=await fetch('/api'+path,{method:body===undefined?'GET':'POST',credentials:'same-origin',headers:body===undefined?{}:{'Content-Type':'application/json'},...(body===undefined?{}:{body:JSON.stringify(body)})});let data;try{data=await response.json();}catch{throw Error('The server returned an unexpected response. Please reload.');}if(!response.ok){if(response.status===401&&!['/login','/password'].includes(path)){currentUser=null;render();}throw Error(data.error||'The request could not be completed.');}return data;}
async function refreshData(){const data=await api('/state');currentUser=data.user;DEMO_DATE=data.date;state=data;if(data.plans)plans.splice(0,plans.length,...data.plans);selectedMember=currentUser.role==='member'?currentUser.memberId:state.members.some(m=>m.id===selectedMember)?selectedMember:state.members[0]?.id||'';if(!selectedMember&&mode==='member')mode='admin';render();}
async function boot(){document.getElementById('app').innerHTML='<div class="loading-screen"><span class="brandmark">F</span><p>Opening your membership workspace…</p></div>';try{const planData=await api('/plans');if(planData.plans?.length)plans.splice(0,plans.length,...planData.plans);const data=await api('/session');ownerLoginAllowed=data.canOwnerLogin;currentUser=data.user;DEMO_DATE=data.date;authReady=true;if(currentUser){mode=currentUser.role==='admin'?'admin':'member';section='overview';await refreshData();}else render();if(location.hash.startsWith('#/set-password'))await passwordSetup();}catch(e){document.getElementById('app').innerHTML=`<div class="loading-screen"><span class="brandmark">F</span><h2>We couldn’t open the workspace.</h2><p>${esc(e.message)}</p>${btn('Try again','reload','primary')}</div>`;}}
function authView(){document.title='FORM Fitness · Sign in';return `<div class="auth-shell"><section class="auth-story"><a class="brand" href="/"><span class="brandmark">F</span><span class="brandword">FORM<small>FITNESS CLUB</small></span></a><div class="auth-story-copy"><div class="eyebrow">A LITTLE PROGRESS, EVERY DAY</div><h1>Your next chapter<br>starts here.</h1><p>Your membership, payments, and gym pass.<br>All in one place. Always moving forward.</p><div class="auth-orbit">${icon('leaf')}</div></div><small>Private membership workspace · FORM Fitness</small></section><main class="auth-panel"><div class="auth-form-wrap"><div class="eyebrow">WELCOME TO YOUR COMMUNITY</div><h2>Good to see you.</h2><p class="auth-sub">Members and administrators sign in with their own accounts.</p><form id="login-form"><div class="field"><label for="login-email">Email address</label><input id="login-email" type="email" autocomplete="username" required maxlength="100"></div><div class="field"><label for="login-password">Password</label><input id="login-password" type="password" autocomplete="current-password" required maxlength="128"></div><div class="form-error" id="login-error" role="alert"></div><button class="button primary auth-submit" type="submit">Log in ${icon('arrow')}</button></form><button class="text-button" data-action="forgot-password">Forgot your password?</button><div class="auth-divider"><span>NEW TO FORM?</span></div>${btn('Create a member account','register','','','plus')}<p class="auth-help">Choose your membership plan during registration. Your mobile number and email are required.</p>${ownerLoginAllowed?`<div class="owner-login">${icon('lock')}<div><strong>Manage your gym</strong><small>Use your verified site-owner account.</small></div>${btn('Admin sign in','owner-login','small')}</div>`:''}<div class="auth-footer">${icon('lock')}This site remains private. A member account does not change who can access the site.</div></div></main></div>`;}
header=function(){let html=baseHeader();return html.replaceAll('Private prototype','Private workspace').replaceAll('Member demo view','Member account').replaceAll('Preview member','Preview member').replaceAll('Class demo guide','Workspace guide');};
footer=function(){return `</div><footer class="page-footer"><span>${icon('lock')}FORM FITNESS · Saved securely to your gym workspace</span>${currentUser?.role==='admin'?'<button data-action="settings">Payment & Gmail settings</button>':'<button data-action="password">Change password</button>'}</footer></main></div>`;};
render=function(){if(!authReady)return;if(!currentUser){document.getElementById('app').innerHTML=authView();return;}if(currentUser.role==='member'){mode='member';selectedMember=currentUser.memberId;}if(mode==='member'&&!memberById(selectedMember)){mode='admin';section='overview';}baseRender();const top=document.querySelector('.top-actions');if(currentUser.role==='member')document.querySelector('.mode-switch')?.remove();else{const preview=document.querySelector('[data-mode="member"]');if(preview){preview.textContent='Member preview';preview.disabled=!state.members.length;}top.insertAdjacentHTML('afterbegin',btn('Scan member','scanner','','','card'));}document.querySelector('.notification')?.remove();top.insertAdjacentHTML('beforeend',`<button class="icon-button" data-action="${currentUser.role==='admin'?'settings':'password'}" aria-label="${currentUser.role==='admin'?'Open settings':'Change password'}">${icon(currentUser.role==='admin'?'grid':'lock')}</button><button class="icon-button" data-action="logout" aria-label="Log out" title="Log out">${icon('logout')}</button>`);document.querySelector('[data-action="guide"]')?.setAttribute('aria-label','Workspace guide');};
payments=function(){let html=basePayments().replaceAll('Try a simulated payment.','Submit a payment for confirmation.').replaceAll('View your invoices and try a simulated payment.','View invoices, receipts, and payment confirmations.').replaceAll('Demo payment','Pay by QR').replaceAll('Payments are recorded manually for this demo.','Confirm payments against your GCash, bank, or cash records.').replaceAll('Demo payments simulate a transaction. No money is collected.','QR payments stay pending until the gym confirms receipt.');const list=(state.submissions||[]).filter(s=>currentUser.role==='admin'||s.memberId===selectedMember);if(list.length)html+=`<section class="panel" style="margin-top:22px"><div class="panel-header"><div><h2>${currentUser.role==='admin'?'Payment review inbox':'Submitted payments'}</h2><p>Submitting a reference does not automatically confirm payment.</p></div>${btn('Refresh','refresh','small')}</div><div class="table-scroll"><table class="data-table"><thead><tr><th>Member</th><th>Method / reference</th><th>Amount</th><th>Status</th><th>Action</th></tr></thead><tbody>${list.map(s=>`<tr><td>${esc(memberById(s.memberId)?.name||s.memberId)}</td><td>${esc(s.method)}<br><small>${esc(s.reference)}</small></td><td>${money(s.amount)}</td><td>${badge(s.status[0].toUpperCase()+s.status.slice(1))}</td><td>${currentUser.role==='admin'&&s.status==='pending'?btn('Review','review-payment','small',`data-id="${s.id}"`):'—'}</td></tr>`).join('')}</tbody></table></div></section>`;return html;};
memberOverview=function(){let html=baseMemberOverview().replaceAll('Try a demo payment','Pay by QR').replaceAll('This is a classroom demo.','Your live member pass.').replaceAll('All sample people and transactions are fictional.','Use your account’s time-limited QR for staff-verified check-in.').replaceAll('There are no automatic renewals in this prototype.','Renewals are not charged automatically.');if(currentUser.role==='member')html=html.replace(/<label class="member-selector">[\s\S]*?<\/label>/,'');html=html.replace('<section class="member-hero">',`<div class="member-pass-bar"><span>${icon('card')}Your pass to a stronger day.</span>${btn('Show my member QR','member-qr','primary','','arrow')}</div><section class="member-hero">`);return html;};
memberMembership=function(){return baseMemberMembership().replace('Your membership, your goals, your next step.','Keep your contact details current and show your member pass.');};
closeModal=function(){if(scanner){scanner.destroy();scanner=null;}if(passTimer){clearInterval(passTimer);passTimer=null;}baseCloseModal();};
registrationModal=function(){baseRegistrationModal();const r=registration;if(r.step===1){const phone=document.getElementById('phone');phone.required=true;phone.removeAttribute('pattern');phone.closest('.field').querySelector('label').textContent='Mobile number *';phone.closest('.field').querySelector('small').textContent='Required · 09XXXXXXXXX or +639XXXXXXXXX';if(!currentUser)document.querySelector('#register-form .form-grid').insertAdjacentHTML('beforeend',`<div class="field full"><label for="new-password">${currentUser?'Initial account password':'Create password'} *</label><input id="new-password" type="password" required minlength="12" maxlength="128" autocomplete="new-password" value="${esc(r.password||'')}"><small>12–128 characters, with at least one letter and one number. ${currentUser?'The member can change it after login.':''}</small></div>`);document.querySelector('.modal .notice').textContent='Use the member’s actual email and mobile number. Notifications are queued for the configured Gmail sender; no invitation or notification is marked sent until Gmail accepts it.';}if(r.step===2){const start=document.getElementById('start');start.min=DEMO_DATE;start.max=addDays(DEMO_DATE,365);}document.querySelector('.modal-head p').textContent=currentUser?'Create a member account with validated contact details.':'Your account and membership, in one simple registration.';};
function validateContactFields(name,email,phone){if(name.trim().length<2)throw Error('Enter your full name.');if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim()))throw Error('Enter a valid email address.');if(!/^(09\d{9}|\+639\d{9})$/.test(phone.replace(/[\s()-]/g,'')))throw Error('Mobile number is required. Use 09XXXXXXXXX or +639XXXXXXXXX.');}
submitRegistration=async function(){const r=registration;if(r.step===1){const name=document.getElementById('full-name').value,email=document.getElementById('email').value,phone=document.getElementById('phone').value;validateContactFields(name,email,phone);const password=document.getElementById('new-password')?.value||'';if(!currentUser&&(password.length<12||!/[a-z]/i.test(password)||!/\d/.test(password)))throw Error('Use a password of at least 12 characters with a letter and a number.');r.password=password;baseSubmitRegistration();return;}if(r.step===2){const start=document.getElementById('start').value;if(!start||start<DEMO_DATE||start>addDays(DEMO_DATE,365))throw Error('Choose a start date within the next year.');baseSubmitRegistration();return;}validateContactFields(r.name,r.email,r.phone);const wasAdmin=!!currentUser;const result=await api(wasAdmin?'/members':'/signup',{name:r.name,email:r.email,phone:r.phone,goal:r.goal,password:r.password,plan:r.plan,start:r.start});registration=null;closeModal();
if(wasAdmin){await refreshData();openModal('Member account created','Send the one-time setup link securely to the member.', '<p>The member chooses their own password. This link is shown once and must be treated as confidential.</p><div class="field"><label for="setup-link">One-time password setup link</label><textarea id="setup-link" readonly rows="4">'+esc(result.setupUrl)+'</textarea></div><div class="notice">Membership activates only after confirmed payment.</div>',btn('Done','close','primary'));return;}
const session=await api('/session');currentUser=session.user;mode='member';section='overview';await refreshData();toast('Account created. Your membership is awaiting payment.');};
pay=function(id){paymentIntent=crypto.randomUUID();const inv=state.invoices.find(i=>i.id===id);if(!inv||balance(inv)<=0)return toast('This invoice is already settled.');paymentInvoice=id;if(currentUser.role==='admin'){basePay(id);document.getElementById('modal-title').textContent='Record a confirmed payment';document.querySelector('.modal-head p').textContent='Verify the money was received before recording it.';document.querySelector('.modal .notice').innerHTML='<strong>Confirm receipt of funds.</strong> A reference number or a QR scan alone does not prove payment.';document.getElementById('payment-form').insertAdjacentHTML('beforeend','<label class="checkline"><input id="funds-verified" type="checkbox" required>I verified this payment in the gym’s GCash, bank, or cash records.</label>');return;}checkoutModal(inv);};
function checkoutModal(inv,method='GCash'){paymentInvoice=inv.id;const key=method==='GCash'?'gcash':'bank',target=state.settings?.payments?.[key];openModal('Pay your membership','Scan with your GCash or banking app.',`<div class="payment-methods"><button class="button ${method==='GCash'?'primary':''}" data-action="checkout-method" data-method="GCash">GCash</button><button class="button ${method==='Bank transfer'?'primary':''}" data-action="checkout-method" data-method="Bank transfer">Bank transfer</button></div>${target?`<div class="payment-qr"><img src="${esc(target.image)}" alt="${esc(method)} recipient QR code"><div><small>PAY TO</small><strong>${esc(target.name)}</strong><p>${esc(target.detail)}</p><p>Invoice balance: <b>${money(balance(inv))}</b></p><a class="button small" href="${esc(target.image)}" download="FORM-${key}-payment-QR.png">Download QR</a></div></div><form id="checkout-form"><input type="hidden" id="checkout-method" value="${method}"><div class="form-grid">${field('Amount sent (PHP) *','checkout-amount',balance(inv),'number',`required min="0.01" max="${balance(inv)}" step="0.01"`)}${field('Transaction reference *','checkout-reference','','text','required minlength="6" maxlength="80"')}<div class="field full"><label for="payment-proof">Receipt image (optional)</label><input type="file" id="payment-proof" accept="image/png,image/jpeg,image/webp"><small>PNG, JPEG, or WebP · maximum 650 KB</small></div></div><label class="checkline"><input type="checkbox" required>I completed this payment in my GCash or banking app and checked the recipient.</label><div class="form-error" id="form-error" role="alert"></div></form><div class="notice">Payment stays pending until your gym verifies receipt. Do not pay again while a submission is being reviewed.</div>`:`<div class="empty">${icon('wallet')}<h3>${method} is not set up yet.</h3><p>Your gym administrator needs to upload the actual recipient QR.<br>No payment destination is shown until it has been configured.</p></div>`}`,`${btn('Close','close')}${target?'<div class="right"><button class="button primary" type="submit" form="checkout-form">Submit for verification</button></div>':''}`);}
submitPayment=async function(){const inv=state.invoices.find(i=>i.id===paymentInvoice);const result=await api('/payments',{invoiceId:inv.id,amount:Number(document.getElementById('amount').value),method:document.getElementById('method').value,date:document.getElementById('payment-date').value,reference:document.getElementById('reference').value,verified:document.getElementById('funds-verified').checked,idempotencyKey:paymentIntent});await refreshData();openModal('Payment confirmed','Your records and membership status are updated.',`<div class="success"><div class="success-symbol">${icon('check')}</div><h3>All recorded.</h3><p>${money(result.payment.amount)} has been recorded. The receipt is available below, and a notification is queued for the member.</p></div>`,`${btn('View receipt','receipt','',`data-id="${result.payment.id}"`)}<div class="right">${btn('Done','close','primary')}</div>`);};
// Receipts represent administrator-confirmed transactions, not processor-generated proof.
const oldReceipt=receipt;receipt=function(id){oldReceipt(id);document.querySelector('.modal-head p').textContent='FORM Fitness · Recorded payment';document.querySelector('.modal .notice').textContent='This receipt records the gym administrator’s confirmation of payment.';};
async function imageFile(input){const f=input?.files?.[0];if(!f)return undefined;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>650000)throw Error('Choose a PNG, JPEG, or WebP image under 650 KB.');return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('The image could not be read.'));r.readAsDataURL(f);});}
function reviewPayment(id){const s=state.submissions.find(x=>x.id===id);if(!s)return;openModal('Verify this payment','Check your own GCash or bank transaction history first.',`<div class="review-card"><div class="detail-item"><span>Member</span><strong>${esc(memberById(s.memberId)?.name)}</strong></div><div class="detail-item"><span>Method</span><strong>${esc(s.method)}</strong></div><div class="detail-item"><span>Reference</span><strong>${esc(s.reference)}</strong></div><div class="detail-item"><span>Amount</span><strong>${money(s.amount)}</strong></div></div>${s.receipt?`<img class="proof-image" src="${esc(s.receipt)}" alt="Submitted transaction receipt">`:''}<form id="review-form"><input id="review-id" type="hidden" value="${s.id}"><label class="checkline"><input id="review-verified" type="checkbox" required>I matched the recipient, amount, and reference to funds actually received.</label><div class="form-error" id="form-error" role="alert"></div></form>`,`${btn('Reject submission','reject-payment','',`data-id="${s.id}"`)}<div class="right"><button class="button primary" type="submit" form="review-form">Confirm payment</button></div>`);}
editProfile=function(){if(currentUser.role!=='member')return toast('Log in to the member account to edit its profile.');baseEditProfile();document.querySelector('.modal-head p').textContent='Keep your contact details and identification photo current.';document.getElementById('edit-phone').required=true;document.getElementById('edit-phone').removeAttribute('pattern');document.getElementById('edit-email').readOnly=true;document.querySelector('#profile-form .form-grid').insertAdjacentHTML('beforeend','<div class="field full"><label for="profile-photo">Member photo (optional)</label><input id="profile-photo" type="file" accept="image/png,image/jpeg,image/webp"><small>Used by staff when checking your QR pass. PNG, JPEG, or WebP · maximum 650 KB.</small></div>');};
function passwordModal(){openModal('Change your password','Use a unique password for your member account.',`<form id="password-form"><div class="form-grid">${field('Current password *','current-password','','password','required autocomplete="current-password"')}${field('New password *','updated-password','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}</div><p class="auth-help">Use at least 12 characters, including a letter and a number.</p><div class="form-error" id="form-error" role="alert"></div></form>`,`${btn('Cancel','close')}<div class="right"><button class="button primary" type="submit" form="password-form">Update password</button></div>`);}
async function memberQR(){if(currentUser.role!=='member')return toast('A live pass is available only in the member’s signed-in account.');const m=memberById(currentUser.memberId);if(memberStatus(m)!=='Active')return openModal('Your member pass','An active membership is required for gym check-in.',`<div class="empty"><h3>${memberStatus(m)} membership</h3><p>Complete your payment or contact the gym before checking in.</p></div>`,btn('Done','close','primary'));const result=await api('/qr');closeModal();openModal('Your member QR','Show this pass to the gym’s staff scanner.',`<div class="member-qr"><canvas id="member-qr-canvas" aria-label="Time-limited member QR code"></canvas><strong>${esc(m.name)}</strong><span>${esc(m.id)}</span><p id="qr-countdown" aria-live="polite"></p></div><div class="notice">This pass confirms your membership account. Staff will also match your photo or photo ID before recording a check-in.</div>`,`${btn('Close','close')}<div class="right">${btn('Refresh pass','member-qr','primary','','reset')}</div>`);await FORM_QR.toCanvas(document.getElementById('member-qr-canvas'),result.token,{width:250,margin:2,errorCorrectionLevel:'M',color:{dark:'#143d32',light:'#ffffff'}});const update=()=>{const n=Math.max(0,result.expires-Math.floor(Date.now()/1000));const el=document.getElementById('qr-countdown');if(!el)return;if(!n){el.textContent='Pass expired. Refresh to get a new QR.';document.getElementById('member-qr-canvas').style.opacity='.15';clearInterval(passTimer);}else el.textContent=`Pass expires in ${n} seconds`;};update();passTimer=setInterval(update,1000);}
async function scannerModal(){if(currentUser.role!=='admin')return;closeModal();openModal('Verify a member','Scan a live FORM pass, then compare the member’s identity.',`<div class="scanner-video"><video id="scan-video" playsinline muted></video><div class="scan-corners"></div></div><p id="scanner-status" class="scanner-status" role="status">Starting your camera…</p><div class="scan-alternatives"><div class="field"><label for="scan-file">Or scan a QR image</label><input id="scan-file" type="file" accept="image/*"></div><details><summary>Use QR text instead</summary><form id="scan-text-form"><div class="field"><label for="scan-text">Member QR text</label><textarea id="scan-text" required maxlength="1000" rows="3"></textarea></div><button class="button" type="submit">Verify pass</button></form></details></div><div class="form-error" id="form-error" role="alert"></div>`,btn('Close scanner','close'));try{const {default:QrScanner}=await import('/vendor/qr-scanner.min.js');if(!document.getElementById('scan-video'))return;scanner=new QrScanner(document.getElementById('scan-video'),r=>{if(scanner)scanner.stop();verifyScanned(r.data).catch(e=>{error(e.message);const s=document.getElementById('scanner-status');if(s)s.textContent='Try another pass or reopen the scanner.';});},{preferredCamera:'environment',returnDetailedScanResult:true,highlightScanRegion:true});await scanner.start();document.getElementById('scanner-status').textContent='Point the camera at the member’s QR code.';}catch{const el=document.getElementById('scanner-status');if(el)el.textContent='Camera unavailable or permission denied. You can upload a QR image instead.';}}
async function verifyScanned(token){const data=await api('/scan',{token});lastScannedToken=token;closeModal();const m=data.member;openModal('Membership verified','Confirm the person matches before checking them in.',`<div class="scan-member">${m.photo?`<img src="${esc(m.photo)}" alt="${esc(m.name)} member photo">`:avatar(m)}<div><h3>${esc(m.name)}</h3><p>${m.id}</p>${badge('Active')}</div></div><div class="review-card"><div class="detail-item"><span>Mobile</span><strong>${esc(m.phone)}</strong></div><div class="detail-item"><span>Plan</span><strong>${planOf(m.plan).name}</strong></div><div class="detail-item"><span>Valid until</span><strong>${date(m.end)}</strong></div></div><form id="checkin-form"><label class="checkline"><input id="identity-confirmed" type="checkbox" required>${m.photo?'I matched this person to their member photo or photo ID.':'I checked this person’s photo ID and it matches the member details.'}</label><div class="form-error" id="form-error" role="alert"></div></form>`,`${btn('Cancel','close')}<div class="right"><button class="button primary" type="submit" form="checkin-form">Confirm check-in</button></div>`);}
function settingsModal(tab=settingsTab){settingsTab=tab;const p=state.settings?.payments||{},email=state.settings?.email||{};let body=`<div class="tabs"><button class="tab ${tab==='payments'?'active':''}" data-action="settings-tab" data-tab="payments">Payment QR codes</button><button class="tab ${tab==='gmail'?'active':''}" data-action="settings-tab" data-tab="gmail">Gmail sender</button><button class="tab ${tab==='mail-log'?'active':''}" data-action="settings-tab" data-tab="mail-log">Notifications</button></div>`,foot=btn('Close','close');if(tab==='payments'){body+=`<form id="payment-settings-form"><div class="settings-qr-grid">${[['gcash','GCash'],['bank','Bank transfer']].map(([k,label])=>`<div class="settings-qr-card"><h3>${label}</h3>${p[k]?.image?`<img src="${esc(p[k].image)}" alt="Saved ${label} QR">`:'<div class="qr-placeholder">No recipient QR uploaded</div>'}<div class="field"><label for="${k}-image">${p[k]?'Replace':'Upload'} actual payment QR</label><input id="${k}-image" type="file" accept="image/png,image/jpeg,image/webp"><small>PNG, JPEG, or WebP · up to 650 KB</small></div>${field('Recipient account name',k+'-name',p[k]?.name||'','text','maxlength="100"')}${field(k==='bank'?'Bank name / payment instructions':'GCash number / payment instructions',k+'-detail',p[k]?.detail||'','text','maxlength="120"')}</div>`).join('')}</div><div class="notice">Upload the QR generated by your own GCash or bank app. Confirm the recipient name matches before saving. The gym verifies submitted payments manually.</div><div class="form-error" id="form-error" role="alert"></div></form>`;foot+='<div class="right"><button class="button primary" type="submit" form="payment-settings-form">Save payment QR codes</button></div>';}else if(tab==='gmail'){body+=`<div class="connection-status">${icon('wallet')}<div><strong>${email.connected?'Gmail sender connected':'Gmail sender not connected'}</strong><p>${email.connected?esc(email.address):'Notifications remain queued until you connect a sender.'}</p></div>${email.connected?btn('Disconnect','disconnect-email','small'):''}</div><form id="gmail-settings-form"><div class="form-grid">${field('Sender Gmail address *','gmail-address',email.address||'','email','required autocomplete="username"')}${field('Google app password *','gmail-password','','password','required autocomplete="new-password" minlength="16" maxlength="24"')}</div><div class="notice">Use a Google app password, not your normal Gmail password. Google requires 2-Step Verification and an eligible account. <a href="https://myaccount.google.com/apppasswords" target="_blank" rel="noopener noreferrer">Create an app password ↗</a>. Your sender credential is encrypted and is never returned to the browser after saving.</div><div class="form-error" id="form-error" role="alert"></div></form><p class="auth-help">This website’s sender setup is separate from connecting Gmail to ChatGPT. Saving validates the sender and queues a test email to that same Gmail address.</p>`;foot+='<div class="right"><button class="button primary" type="submit" form="gmail-settings-form">Connect & send test email</button></div>';}else{body+=`<p class="auth-help">“Sent” means Gmail accepted the message. It does not guarantee inbox placement. For an unconfirmed delivery, check Gmail Sent before retrying.</p><div class="table-scroll"><table class="data-table"><thead><tr><th>Notification</th><th>Status</th><th>Action</th></tr></thead><tbody>${state.outbox?.length?state.outbox.map(m=>`<tr><td><strong>${esc(m.subject)}</strong><br><small>${esc(m.recipient)}</small>${m.error?`<p style="white-space:normal;font-size:10px;margin-top:6px">${esc(m.error)}</p>`:''}</td><td>${badge(m.status==='needs_review'?'Needs review':m.status[0].toUpperCase()+m.status.slice(1))}</td><td>${m.status==='needs_review'?btn('Review retry','retry-email','small',`data-id="${m.id}"`):'—'}</td></tr>`).join(''):'<tr><td colspan="3">No notifications yet.</td></tr>'}</tbody></table></div>`;foot+=`<div class="right">${btn('Refresh','refresh-email','')}${btn('Send queued','send-queued','primary')}</div>`;}openModal('Workspace settings','Your payment destinations and notification sender.',body,foot,true);}
guide=function(){openModal('Your connected workspace','A complete membership journey.',`<div class="guide-step"><i>1</i><div><strong>Set up payments and Gmail</strong><p>Upload the actual GCash and bank QR images in Settings. Connect a Gmail sender with a Google app password to deliver queued notifications.</p></div></div><div class="guide-step"><i>2</i><div><strong>Register with complete contact details</strong><p>Members need a name, email, valid Philippine mobile number, password, and selected plan. Staff can also create accounts.</p></div></div><div class="guide-step"><i>3</i><div><strong>Confirm funds received</strong><p>Members scan your payment QR in their payment app and submit a transaction reference. Staff verify receipt before approving. A QR scan alone never activates a membership.</p></div></div><div class="guide-step"><i>4</i><div><strong>Verify a live member pass</strong><p>Active members display a QR valid for 90 seconds. Staff scan it, match the member’s photo or photo ID, and confirm check-in.</p></div></div><div class="notice">Data is persistent. There is no demo reset. The site remains private; member accounts do not grant access through the separate site privacy gate.</div>`,btn('Got it','close','primary'));};
async function runForm(form,operation){const button=document.querySelector(`button[form="${form.id}"]`)||form.querySelector('[type="submit"]');if(button)button.disabled=true;try{await operation();}catch(e){const target=form.querySelector('.form-error')||document.querySelector('.modal .form-error');if(target)target.textContent=e.message;else toast(e.message);}finally{if(button?.isConnected)button.disabled=false;}}
document.addEventListener('submit',event=>{const form=event.target;const handlers={
 'login-form':async()=>{await api('/login',{email:document.getElementById('login-email').value,password:document.getElementById('login-password').value});const session=await api('/session');currentUser=session.user;mode=currentUser.role==='admin'?'admin':'member';section='overview';await refreshData();},
 'register-form':submitRegistration,
 'payment-form':submitPayment,
 'checkout-form':async()=>{await api('/payment-submissions',{invoiceId:paymentInvoice,method:document.getElementById('checkout-method').value,amount:Number(document.getElementById('checkout-amount').value),reference:document.getElementById('checkout-reference').value,receipt:await imageFile(document.getElementById('payment-proof'))});await refreshData();closeModal();navigate('payments');toast('Payment submitted. It remains pending until verified by the gym.');},
 'review-form':async()=>{await api('/review-payment',{id:document.getElementById('review-id').value,approve:true,verified:document.getElementById('review-verified').checked});await refreshData();closeModal();toast('Payment verified and membership balance updated.');},
 'profile-form':async()=>{const name=document.getElementById('edit-name').value,email=document.getElementById('edit-email').value,phone=document.getElementById('edit-phone').value;validateContactFields(name,email,phone);await api('/profile',{name,email,phone,goal:document.getElementById('edit-goal').value,photo:await imageFile(document.getElementById('profile-photo'))});await refreshData();closeModal();toast('Member profile saved.');},
 'password-form':async()=>{await api('/password',{currentPassword:document.getElementById('current-password').value,newPassword:document.getElementById('updated-password').value});closeModal();toast('Password updated. Other sessions have been signed out.');},
 'scan-text-form':async()=>{await verifyScanned(document.getElementById('scan-text').value.trim());},
 'checkin-form':async()=>{await api('/check-in',{token:lastScannedToken,confirmed:document.getElementById('identity-confirmed').checked});await refreshData();closeModal();toast('Check-in confirmed. Member notification queued.');},
 'payment-settings-form':async()=>{const result={};for(const k of ['gcash','bank']){const image=await imageFile(document.getElementById(k+'-image'))||state.settings?.payments?.[k]?.imagePath;if(image)result[k]={image,name:document.getElementById(k+'-name').value,detail:document.getElementById(k+'-detail').value};}await api('/settings/payments',result);await refreshData();settingsModal('payments');toast('Payment QR codes saved.');},
 'gmail-settings-form':async()=>{await api('/settings/email',{address:document.getElementById('gmail-address').value,appPassword:document.getElementById('gmail-password').value});await refreshData();settingsModal('mail-log');toast('Gmail connected. Your test notification is queued.');}
};if(handlers[form.id]){event.preventDefault();event.stopImmediatePropagation();runForm(form,handlers[form.id]);}},true);
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;const actions={
 'reload':()=>boot(),
 'owner-login':async()=>{await api('/owner-login',{});const session=await api('/session');currentUser=session.user;mode='admin';section='overview';await refreshData();},
 'logout':async()=>{await api('/logout',{});closeModal();currentUser=null;state={members:[],invoices:[],payments:[],activity:[]};render();toast('You have been logged out.');},
 'settings':()=>settingsModal(),
 'settings-tab':()=>settingsModal(el.dataset.tab),
 'password':()=>passwordModal(),
 'refresh':()=>refreshData(),
 'member-qr':()=>memberQR(),
 'scanner':()=>scannerModal(),
 'checkout-method':()=>checkoutModal(state.invoices.find(i=>i.id===paymentInvoice),el.dataset.method),
 'review-payment':()=>reviewPayment(el.dataset.id),
 'reject-payment':()=>openModal('Reject this payment submission?','The member will be notified to contact the gym.',`<p class="confirm-copy">Only reject a submission after checking your payment records. No balance will be marked paid.</p>`,`${btn('Cancel','close')}<div class="right">${btn('Reject submission','confirm-reject','danger',`data-id="${el.dataset.id}"`)}</div>`),
 'confirm-reject':async()=>{await api('/review-payment',{id:el.dataset.id,approve:false});await refreshData();closeModal();toast('Submission rejected. Notification queued.');},
 'disconnect-email':async()=>{await api('/settings/email',{disconnect:true});await refreshData();settingsModal('gmail');},
 'refresh-email':async()=>{await refreshData();settingsModal('mail-log');},
 'send-queued':async()=>{await api('/email-retry',{});await refreshData();settingsModal('mail-log');toast('Queued notifications are being processed.');},
 'retry-email':()=>openModal('Review before retrying','Avoid sending a notification twice.',`<p class="confirm-copy">Search Gmail Sent for this notification. Retry only if it was not sent.</p>`,`${btn('Cancel','close')}<div class="right">${btn('Not sent — retry','confirm-retry-email','primary',`data-id="${el.dataset.id}"`)}</div>`),
 'confirm-retry-email':async()=>{await api('/email-retry',{id:el.dataset.id,checked:true});await refreshData();settingsModal('mail-log');},
 'reset':()=>toast('This is a connected workspace. Persistent member records cannot be reset here.'),
 'confirm-reset':()=>toast('Reset is unavailable for connected records.'),
 'guide-start':()=>guide(),
 'download-receipt':()=>{const p=state.payments.find(x=>x.id===el.dataset.id),m=memberById(p.memberId);download(`FORM-receipt-${p.id}.txt`,['FORM FITNESS — RECORDED PAYMENT RECEIPT','Payment confirmed by the gym administrator.','',`Receipt: ${p.id}`,`Member: ${m.name} (${m.id})`,`Invoice: ${p.invoiceId}`,`Date: ${date(p.date)}`,`Method: ${p.method}`,`Reference: ${p.reference||'Cash payment'}`,`Amount paid: PHP ${p.amount.toFixed(2)}`].join('\n'));toast('Receipt downloaded.');}
};if(actions[a]){event.preventDefault();event.stopImmediatePropagation();el.disabled=true;Promise.resolve().then(actions[a]).catch(e=>{if(document.getElementById('form-error'))error(e.message);else toast(e.message);}).finally(()=>{if(el.isConnected)el.disabled=false;});}else if(a==='mode'&&(currentUser?.role!=='admin'||(el.dataset.mode==='member'&&!state.members.length))){event.stopImmediatePropagation();toast('No member is available to preview yet.');}},true);
document.addEventListener('change',async event=>{if(event.target.id==='scan-file'&&event.target.files?.[0]){try{const {default:QrScanner}=await import('/vendor/qr-scanner.min.js');const result=await QrScanner.scanImage(event.target.files[0],{returnDetailedScanResult:true});await verifyScanned(result.data);}catch(e){error(e.message||'No readable member QR was found in that image.');}}});
function recoveryModal(){openModal('Reset your password','We will send a setup link to your account email.',`<form id="recovery-form">${field('Email address *','recovery-email','','email','required autocomplete="email"')}<div class="form-error" id="form-error" role="alert"></div></form>`,`${btn('Cancel','close')}<button class="button primary" form="recovery-form" type="submit">Send recovery link</button>`);}
async function passwordSetup(){
  const query=new URLSearchParams(location.hash.split('?')[1]||'');
  const tokenHash=query.get('token_hash');
  history.replaceState({},'',location.pathname+'#/set-password');
  if(tokenHash){await api('/auth/verify',{type:query.get('type'),tokenHash});const session=await api('/session');currentUser=session.user;if(currentUser){mode=currentUser.role==='admin'?'admin':'member';await refreshData();}}
  if(!currentUser)return openModal('Sign in to set your password','Open a fresh invitation or recovery link.','<p>The link may have expired. Request password recovery or contact your gym administrator.</p>',btn('Close','close'));
  openModal('Set your password','Choose a strong password for your account.',`<form id="setup-password-form">${field('New password *','setup-password','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}<div class="form-error" id="form-error" role="alert"></div></form>`,`<button class="button primary" form="setup-password-form" type="submit">Save password</button>`);
}
selectPlan=function(id){
  const p=planOf(id),m=memberById(selectedMember);
  const last=(state.memberships||[]).filter(c=>c.member_id===m.id).map(c=>c.end_date).sort().at(-1)||m.end;
  const start=last>=DEMO_DATE?addDays(last,1):DEMO_DATE;
  openModal('Create your next membership cycle','Review the plan before creating an invoice.',`<form id="renew-form"><input type="hidden" id="renew-plan" value="${esc(p.id)}"><input type="hidden" id="renew-member" value="${esc(m.id)}"><div class="review-card"><h3>${esc(p.name)}</h3><p>${money(p.price)} · ${p.days||30} days</p></div>${field('Start date *','renew-start',start,'date',`required min="${start}" max="${addDays(DEMO_DATE,365)}"`)}<div class="notice">This creates a real invoice. No payment is taken automatically. Your paid current cycle remains valid; the new cycle activates only when fully paid and its start date is reached.</div><label class="checkline"><input type="checkbox" required>I confirm this membership cycle and invoice.</label><div class="form-error" id="form-error" role="alert"></div></form>`,`${btn('Cancel','close')}<button class="button primary" form="renew-form" type="submit">Create renewal invoice</button>`);
};
const baseProfile=profile;
profile=function(id){baseProfile(id);if(currentUser.role==='admin'){const m=memberById(id);document.querySelector('.modal-footer').insertAdjacentHTML('afterbegin',btn('Reset password','reset-member-password','small',`data-id="${m.id}"`)+btn(m.enabled===false?'Reactivate member':'Deactivate member','toggle-member','small',`data-id="${m.id}"`)+btn('Renew membership','renew-member','small',`data-id="${m.id}"`));}};
const basePlanCards=planCards;
planCards=function(){let html=basePlanCards();if(currentUser?.role==='admin')html+=`<section class="panel" style="margin-top:20px"><div class="panel-header"><h2>Manage plan pricing and availability</h2></div><div class="table-scroll"><table class="data-table"><tbody>${plans.map(p=>`<tr><td>${esc(p.name)}</td><td>${money(p.price)}</td><td>${p.available?'Available':'Unavailable'}</td><td>${btn('Edit plan','edit-plan','small',`data-id="${esc(p.id)}"`)}</td></tr>`).join('')}</tbody></table></div></section>`;return html;};
function editPlan(id){const p=planOf(id);openModal('Edit membership plan','New prices apply only to new invoices.',`<form id="edit-plan-form"><input type="hidden" id="plan-id" value="${esc(id)}">${field('Plan name *','plan-name',p.name,'text','required minlength="2" maxlength="60"')}${field('Price (PHP) *','plan-price',p.price,'number','required min="0.01" max="100000" step="0.01"')}<label class="checkline"><input id="plan-available" type="checkbox" ${p.available?'checked':''}>Available for registration and renewal</label><div class="form-error" id="form-error" role="alert"></div></form>`,`${btn('Cancel','close')}<button class="button primary" type="submit" form="edit-plan-form">Save plan</button>`);}
document.addEventListener('submit',event=>{
  const form=event.target;
  const actions={
    'recovery-form':async()=>{const response=await api('/recovery',{email:document.getElementById('recovery-email').value});closeModal();toast(response.message);},
    'setup-password-form':async()=>{await api('/set-password',{newPassword:document.getElementById('setup-password').value});history.replaceState({},'',location.pathname);closeModal();await boot();toast('Password saved.');},
    'renew-form':async()=>{await api('/renew',{memberId:document.getElementById('renew-member').value,plan:document.getElementById('renew-plan').value,start:document.getElementById('renew-start').value});await refreshData();closeModal();navigate('payments');toast('Renewal invoice created. Payment is still required.');},
    'edit-plan-form':async()=>{await api('/plans',{id:document.getElementById('plan-id').value,name:document.getElementById('plan-name').value,price:document.getElementById('plan-price').value,available:document.getElementById('plan-available').checked});await refreshData();closeModal();toast('Plan saved. Existing invoices are unchanged.');}
  };
  if(actions[form.id]){event.preventDefault();event.stopImmediatePropagation();runForm(form,actions[form.id]);}
},true);
document.addEventListener('click',event=>{
  const el=event.target.closest('[data-action]');if(!el)return;
  const actions={
    'forgot-password':()=>recoveryModal(),
    'edit-plan':()=>editPlan(el.dataset.id),
    'renew-member':()=>{selectedMember=el.dataset.id;selectPlan(memberById(selectedMember).plan);},
    'toggle-member':()=>{const m=memberById(el.dataset.id);openModal(m.enabled===false?'Reactivate member?':'Deactivate member?','Recorded memberships and payments will be preserved.',`<p>${esc(m.name)} ${m.enabled===false?'will regain access.':'will be unable to sign in or use member passes.'}</p>`,`${btn('Cancel','close')}${btn('Confirm','confirm-toggle-member','primary',`data-id="${m.id}"`)}`);},
    'confirm-toggle-member':async()=>{const m=memberById(el.dataset.id);await api('/manage-member',{id:m.id,enabled:m.enabled===false});await refreshData();closeModal();toast('Member access updated.');}
  };
  if(actions[el.dataset.action]){event.preventDefault();event.stopImmediatePropagation();el.disabled=true;Promise.resolve().then(actions[el.dataset.action]).catch(e=>toast(e.message)).finally(()=>{if(el.isConnected)el.disabled=false;});}
},true);
const baseOverview=overview;
overview=function(){return baseOverview()+`<section class="panel" style="margin-top:22px"><div class="panel-header"><div><h2>Recent activity</h2><p>Confirmed payments and staff-verified visits</p></div></div><div class="renewal-list">${state.activity?.length?state.activity.slice(0,8).map(a=>`<div class="renewal-row"><div class="renewal-info"><strong>${esc(a.text)}</strong><small>${date(a.date)}</small></div></div>`).join(''):'<div class="empty"><h3>No activity yet.</h3><p>Confirmed payments and check-ins will appear here.</p></div>'}</div></section>`;};
const localAuthView=authView;
authView=function(){
  if(!canSetup)return localAuthView();
  document.title='FORM Fitness · Local setup';
  return `<div class="auth-shell"><section class="auth-story"><a class="brand" href="/"><span class="brandmark">F</span><span class="brandword">FORM<small>FITNESS CLUB</small></span></a><div class="auth-story-copy"><div class="eyebrow">LOCAL WORKSPACE</div><h1>Your gym,<br>on this computer.</h1><p>Create the administrator account to begin.</p><div class="auth-orbit">${icon('lock')}</div></div><small>Stored on this computer · Not connected to a hosted service</small></section><main class="auth-panel"><div class="auth-form-wrap"><div class="eyebrow">FIRST-TIME SETUP</div><h2>Create administrator</h2><p class="auth-sub">This account controls the local membership workspace.</p><form id="setup-form"><div class="field"><label for="setup-name">Administrator name</label><input id="setup-name" required minlength="2" maxlength="70" autocomplete="name"></div><div class="field"><label for="setup-email">Email address</label><input id="setup-email" type="email" required maxlength="100" autocomplete="email"></div><div class="field"><label for="setup-phone">Mobile number</label><input id="setup-phone" required autocomplete="tel" placeholder="09171234567"></div><div class="field"><label for="setup-password">Password</label><input id="setup-password" type="password" required minlength="12" maxlength="128" autocomplete="new-password"><small>At least 12 characters, including a letter and a number.</small></div><div class="form-error" id="setup-error" role="alert"></div><button class="button primary auth-submit" type="submit">Create local workspace ${icon('arrow')}</button></form><div class="auth-footer">Only this computer can access the workspace. Back up the local data folder to preserve records.</div></div></main></div>`;
};
recoveryModal=function(){openModal('Password reset','Email recovery is unavailable in local-only mode.','<p>Ask the local administrator to help reset this account.</p>',btn('Done','close','primary'));};
const connectedRegistrationModal=registrationModal;
registrationModal=function(){connectedRegistrationModal();const notice=document.querySelector('.modal .notice');if(notice)notice.textContent='Member accounts, photos, invoices, and payment records are saved locally on this computer. No invitation or email is sent.';};
const connectedRegistrationSubmit=submitRegistration;
submitRegistration=async function(){const admin=!!currentUser;await connectedRegistrationSubmit();if(admin&&document.getElementById('setup-link')){document.getElementById('modal-title').textContent='Member account created';document.querySelector('.modal-head p').textContent='Share the password you entered with the member securely.';document.querySelector('.modal-body').innerHTML='<div class="notice">The member can sign in with the password entered during account creation and change it from their account. No email or invitation was sent.</div>';}};
const connectedSettingsModal=settingsModal;
settingsModal=function(tab=settingsTab){
  if(tab==='mail-log'){
    const rows=state.outbox||[];
    openModal('Local notifications','These records stay on this computer and are never emailed.',rows.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>Created</th><th>Recipient</th><th>Notification</th><th>Status</th></tr></thead><tbody>${rows.map(item=>`<tr><td>${date(new Date(item.created*1000).toISOString().slice(0,10))}</td><td>${esc(item.recipient)}</td><td>${esc(item.subject)}</td><td>${badge('Local')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h3>No notifications yet.</h3><p>Local notification records will appear here.</p></div>',btn('Close','close','primary'));
    return;
  }
  if(tab!=='gmail'){
    connectedSettingsModal(tab);
    const emailTab=document.querySelector('.modal [data-tab="gmail"]');
    if(emailTab)emailTab.textContent='Local notifications';
    return;
  }
  settingsTab=tab;
  openModal('Local notifications','Messages are recorded on this computer and are not emailed.',`<div class="connection-status"><div><strong>Email delivery is disabled</strong><p>Notifications remain in the local activity log.</p></div></div><div class="notice">This workspace does not connect to Gmail or any other messaging service.</div>`,`${btn('Close','close')}${btn('View notifications','settings-tab','primary','data-tab="mail-log"')}`);
};
const connectedGuide=guide;
guide=function(){openModal('Local workspace','Keep your gym records on this computer.',`<div class="guide-step"><i>1</i><div><strong>Create member accounts</strong><p>Use a unique password for each member and share it securely. Members can change it after signing in.</p></div></div><div class="guide-step"><i>2</i><div><strong>Record payments carefully</strong><p>Payment details are stored locally. Confirm funds in your own GCash, bank, or cash records before recording or approving a payment.</p></div></div><div class="guide-step"><i>3</i><div><strong>Back up your records</strong><p>Stop the server and copy the .local data file to a secure backup location.</p></div></div><div class="notice">This app listens only on this computer. Email, online payments, and cloud synchronization are not connected.</div>`,btn('Done','close','primary'));};
const connectedFooter=footer;
footer=function(){return connectedFooter().replace('Payment & Gmail settings','Payment settings');};
document.addEventListener('submit',event=>{
  if(event.target.id!=='setup-form')return;
  event.preventDefault();event.stopImmediatePropagation();
  runForm(event.target,async()=>{
    await api('/setup',{name:document.getElementById('setup-name').value,email:document.getElementById('setup-email').value,phone:document.getElementById('setup-phone').value,password:document.getElementById('setup-password').value});
    canSetup=false;const session=await api('/session');currentUser=session.user;mode='admin';section='overview';await refreshData();
  });
},true);
document.addEventListener('click',event=>{
  const button=event.target.closest('[data-action="reset-member-password"]');
  if(!button)return;
  event.preventDefault();event.stopImmediatePropagation();
  const member=memberById(button.dataset.id);
  const temporaryPassword=crypto.randomUUID().replaceAll('-','')+'A1';
  button.disabled=true;
  api('/reset-password',{id:member.id,newPassword:temporaryPassword}).then(()=>{
    openModal('Temporary password created','Share this password with the member privately.',`<div class="field"><label for="temporary-password">Temporary password</label><input id="temporary-password" type="text" readonly value="${esc(temporaryPassword)}"></div><div class="notice">The member has been signed out on other sessions. They can change this password after signing in. This value will not be saved in the notification log.</div>`,btn('Done','close','primary'));
    document.getElementById('temporary-password').select();
  }).catch(error=>toast(error.message)).finally(()=>{if(button.isConnected)button.disabled=false;});
},true);
const connectedBoot=boot;
boot=async function(){try{canSetup=!!(await api('/session')).canSetup;}catch{}return connectedBoot();};
boot();
